def transform(grid):
    sep = next(i for i, row in enumerate(grid) if len(set(row)) == 1)
    top, bottom = grid[:sep], grid[sep + 1:]
    h, w = len(top), len(top[0])

    def foreground(region):
        counts = {}
        for row in region:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        # The patterned color is the less frequent of the two colors.
        return min(counts, key=counts.get)

    a, b = foreground(top), foreground(bottom)
    return [[3 if top[r][c] == a and bottom[r][c] == b else 2
             for c in range(w)] for r in range(h)]
